import json, os, re, zipfile
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
tex = open("pilot-paper/main.tex", encoding="utf-8").read()
ab = tex.split(r"\begin{abstract}")[1].split(r"\end{abstract}")[0].strip()
ab = ab.replace(r"$\eps$", "ε").replace(r"\emph{", "").replace("}", "").replace("~", " ").replace(r"\%", "%").replace(r"\$", "$").replace("$", "")
meta = {"metadata": {
    "title": "Interfaces or Bodies? A 24-Instance Pilot Measurement of ε-Sufficient Context for Language-Model Code Editing in Go",
    "upload_type": "publication", "publication_type": "report", "publication_date": "2026-10-11", "description": "<p>" + ab + "</p>",
    "creators": [{"name": "Johansen, Jude Castiel", "affiliation": "Shockware Limited, independent researcher", "orcid": "0009-0002-5644-3073"}],
    "access_right": "open", "license": "cc-by-4.0",
    "keywords": ["context sufficiency", "language model code editing", "SuffBench", "Go", "prompt length", "interfaces", "pilot study"],
    "related_identifiers": [{"identifier": "10.5281/zenodo.23282195", "relation": "isSupplementTo", "scheme": "doi"},
                            {"identifier": "10.5281/zenodo.23282863", "relation": "references", "scheme": "doi"},
                            {"identifier": "https://github.com/Shockware-Limited/suffbench", "relation": "isSupplementedBy", "resource_type": "software", "scheme": "url"}],
    "version": "0.1.1-pilot", "language": "eng", "contributors": [{"name": "Shockware Limited", "type": "HostingInstitution"}],
    "notes": "Exploratory pilot on one repository and three models of one vendor; it fixes the design of a preregistered study and makes no confirmatory claim. The data zip includes instances, the mining log, the harness and all verdict records."}}
json.dump(meta, open("pilot-paper/zenodo-metadata.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
import shutil, glob; shutil.copy("pilot-paper/main.pdf", "pilot-release/paper/main.pdf"); shutil.copy("pilot-paper/main.tex", "pilot-release/paper/main.tex")
for f in glob.glob("harness/results/cli__cli-*-claude-*.jsonl") + glob.glob("harness/results/pilot_*"): shutil.copy(f, "pilot-release/results/")
rep = open("harness/results/PILOT-REPORT.md", encoding="utf-8").read().replace("(auto-generated by analysis/pilot.py)", "(auto-generated by harness/analysis_pilot.py; released with SuffBench v0.1.1-pilot)")
open("pilot-release/results/PILOT-REPORT.md", "w", encoding="utf-8").write(rep)
for f in glob.glob("harness/instances/cli__cli-*.json"):
    d = json.load(open(f, encoding="utf-8")); d.pop("api_key_file", None); d["repo_path"] = "<local checkout of github.com/cli/cli>"
    d["cutoff_flags"] = {"note": "model training cut-offs not verified against commit date; task-only arm is the operational control", "created_at": d.get("created_at")}
    json.dump(d, open("pilot-release/instances/" + os.path.basename(f), "w", encoding="utf-8"), indent=1)
assert not any("api_key_file" in open(p, encoding="utf-8").read() for p in glob.glob("pilot-release/instances/*.json"))
open("pilot-release/README.md", "w", encoding="utf-8").write("# SuffBench pilot v0.1.1-pilot\n\n24-instance pilot measurement of ε-sufficient context on cli/cli (June–October 2026): Claude Haiku 5.5 (9 arms, k=10, all 24), Claude Sonnet 5.5 (5 arms, k=3, all 24), Claude Opus 5 (3 arms, k=3, the 10 instances Sonnet did not solve from task text alone). See paper/main.pdf. Instances: `instances/`; mining log with every rejection: `instances/rejected.jsonl`; verdict records: `results/*.jsonl`; aggregate: `results/PILOT-REPORT.md`, `results/pilot_cells.csv`; harness and analysis: `harness/`. Exploratory pilot: no confirmatory claim. Data and text CC-BY-4.0; code Apache-2.0.\n")
z = "pilot-paper/suffbench-pilot-v0.1.1.zip"
with zipfile.ZipFile(z, "w", zipfile.ZIP_DEFLATED) as zf:
    for root, _, files in os.walk("pilot-release"):
        for f in files: zf.write(os.path.join(root, f), os.path.relpath(os.path.join(root, f), "."))
print("metadata + zip ok", round(os.path.getsize(z) / 1e6, 2), "MB")
